import math
def priority(task, state, k=1.0, m=5.0):
    slack = max(0.0, task.due - state.now - task.estimated_runtime)
    tier = m if task.tenant == 'premium' else 1.0
    return -slack * tier + (state.now - task.release) / max(task.estimated_runtime, 1e-6)

import math
def priority(task, state, k=1.0, m=5.0):
    slack = max(0.0, task.due - state.now - task.estimated_runtime)
    wait_ratio = (state.now - task.release) / max(task.estimated_runtime, 1e-6)
    urgency = math.exp(-slack / (k * max(state.mean_est, 1e-6)))
    return task.weight * urgency + m * wait_ratio * (1 + k * wait_ratio)

import math
def priority(task, state, k=1.0, m=5.0):
    slack = max(0.0, task.due - state.now - task.estimated_runtime)
    wait_time = state.now - task.release
    tier = m if task.tenant == 'premium' else 1.0
    return -slack * tier + k * wait_time * (1 + k * wait_time / max(task.estimated_runtime, 1e-6))

