def priority(task, state, k=0.5, m=2.0):
    slack = max(0.0, task.due - task.estimated_runtime - state.now)
    wait_time = state.now - task.release
    tier = m if task.tenant == 'premium' else 1.0
    return tier * task.weight / max(task.estimated_runtime, 1e-6) * math.exp(-slack / (k * max(state.mean_est, 1e-6))) + wait_time / max(task.estimated_runtime, 1e-6)

def priority(task, state, a=1.0, b=2.0, c=0.5):
    slack = max(0.0, task.due - task.estimated_runtime - state.now)
    urgency = 1 / (max(slack, 1e-6))
    waiting_ratio = (state.now - task.release) / max(task.estimated_runtime, 1e-6)
    return a * task.weight / max(task.estimated_runtime, 1e-6) * (b * urgency + c * waiting_ratio)

def priority(task, state, k=0.5, m=2.0, n=1.0):
    slack = max(0.0, task.due - task.estimated_runtime - state.now)
    tier = m if task.tenant == 'premium' else 1.0
    queue_pressure = state.queue_work / max(state.capacity, 1e-6)
    return tier * task.weight / max(task.estimated_runtime, 1e-6) * math.exp(-slack / (k * max(state.mean_est, 1e-6))) * (1 + n * queue_pressure)

def priority(task, state, k=0.5, m=2.0, q=1.0):
    slack = max(0.0, task.due - task.estimated_runtime - state.now)
